import { renderPhoto } from "@/lib/media/homepage-photo";

/**
 * One editorial photograph, driven entirely by the acquisition manifest.
 *
 * Renders a plain <img> rather than next/image on purpose: the Cloudflare
 * adapter runs with `images: { unoptimized: true }`, so next/image would add a
 * wrapper and a runtime cost while doing no resizing. Every width in the
 * srcSet is pre-generated by scripts/acquire-homepage-photography.mjs.
 *
 * width/height are always emitted so the browser reserves the correct box
 * before the bytes arrive -- without them a full-bleed hero shifts the entire
 * page as it loads.
 */
export default function EditorialImage({
  slot,
  sizes,
  priority = false,
  className = "",
  alt,
}: {
  slot: string;
  sizes: string;
  /** Only the hero should be priority: everything else is below the fold. */
  priority?: boolean;
  className?: string;
  alt: string;
}) {
  const photo = renderPhoto(slot);
  if (!photo) return null;

  return (
    <img
      src={photo.src}
      srcSet={photo.srcSet}
      sizes={sizes}
      width={photo.width}
      height={photo.height}
      alt={alt}
      loading={priority ? "eager" : "lazy"}
      decoding={priority ? "sync" : "async"}
      fetchPriority={priority ? "high" : "auto"}
      className={className}
    />
  );
}
